            return result == null ? "null" : java.util.Arrays.toString(result);
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("parseLine(\"a, b ,c\")", "[a, b, c]", call("a, b ,c"));
        check("parseLine(\"one\")", "[one]", call("one"));
        check("parseLine(\"a,,c\") keeps empty middle", "[a, , c]", call("a,,c"));
        check("parseLine(\"a,b,\") keeps empty last", "[a, b, ]", call("a,b,"));
        check("parseLine(\" x , y \")", "[x, y]", call(" x , y "));
        check("parseLine(\"10, 20,30\")", "[10, 20, 30]", call("10, 20,30"));
